Hier ist eine C++-Funktion, die den Markdown-Text in HTML formatiert und den resultierenden HTML-Text als std::string zurückgibt:

```cpp
#include <iostream>
#include <string>
#include <regex>
#include <unordered_map>

// Konstruktor für die HTML-Entitäten
struct HTMLChar {
    std::string entity;
    char value;
};

// HTML-Entitäten-Hash-Map
std::unordered_map<char, HTMLChar> html_entities {
    {'&', {'&', '&'}},
    {'<', {'<', '<'}},
    {'>', {'>', '>'}},
    {'\'', {'\'', '\''}},
    {'"', {'"', '"'}}
};

// Funktion zum Formatieren des Markdown-Texts in HTML
std::string markdown_to_html(const std::string& markdown_text) {
    // HTML-Formatierung für Markdown-Konstrukte
    std::regex markdown_regex {
        R"(^(?:#|##|###|####|#####|######)\s(.+)$)",
        std::regex::icase // Case-insensitive matching
    };
    std::string html_text;
    std::string line;
    bool in_list_item = false;
    bool in_block_quote = false;
    int list_item_count = 0;

    // Reguläre Ausdrücke für Markdown-Konstrukte
    std::regex inline_code_regex { R"(`([^`]+)`)" };
    std::regex link_regex { R"((\[([^[\]]*)\])\(([^)]*)\))" };
    std::regex email_regex { R"((\b[\w\.-]+@[\w\.-]+\.\w{2,4}\b))" };
    std::regex strong_regex { R"(__([^_]+)__)" };
    std::regex emphasis_regex { R"(__([^_]+)__|***([^*]+)***|\*\*([^*]+)\*\*)" };
    std::regex linebreak_regex { R"(\\(?:\n|$)|\n{2,})" };
    std::regex space_regex { R"( +)" };
    std::regex escape_regex { R"(\&\w*\;)" };

    // HTML-Formatierung für Markdown-Konstrukte
    for (const auto& line : std::split(markdown_text, "\n")) {
        // Entfernen von Leerzeilen und Leerzeichen
        line = std::regex_replace(line, space_regex, " ");
        line = std::regex_replace(line, linebreak_regex, "<br>");
        if (line.empty()) continue;

        // H1 bis H6-Tags
        std::smatch match;
        if (std::regex_match(line, match, markdown_regex)) {
            const auto& level = match[1].str().size() - 1;
            html_text += std::string(level * 4, '<h') + std::to_string(level + 1) + '>';
            html_text += match[2];
            html_text += std::string(level * 4, '</h' + std::to_string(level + 1) + '>');
            continue;
        }

        // Inline-Codes
        line = std::regex_replace(line, inline_code_regex,
            [&](const std::smatch& match) {
                const auto& code = match[1].str();
                std::string html = "<code>";
                html += std::regex_replace(code, escape_regex, std::strdup("&amp;"));
                html += "</code>";
                return html;
            });

        // Links
        line = std::regex_replace(line, link_regex,
            [&](const std::smatch& match) {
                const auto& text = match[1].str();
                const auto& url = match[3].str();
                std::string html = "<a href=\"";
                html += url;
                html += "\">";
                html += text;
                html += "</a>";
                return html;
            });

        // E-Mail-Adressen
        line = std::regex_replace(line, email_regex,
            [&](const std::smatch& match) {
                const auto& email = match[1].str();
                std::string html = "<a href=\"mailto:";
                html += email;
                html += "\">";
                html += email;
                html += "</a>";
                return html;
            });

        // Fett
        line = std::regex_replace(line, strong_regex,
            [&](const std::smatch& match) {
                const auto& text = match[1].str();
                std::string html = "<strong>";
                html += text;
                html += "</strong>";
                return html;
            });

        // Fettdarstellung
        line = std::regex_replace(line, emphasis_regex,
            [&](const std::smatch& match) {
                const auto& text = match[1].str();
                std::string html;
                switch (match[0].str()[0]) {
                    case '_':
                        html = "<em>";
                        break;
                    case '*':
                        html = "<strong>";
                        break;
                    case '**':
                        html = "<strong><em>";
                        break;
                }
                html += text;
                html += "</" + match[0].str()[0] + ">";
                return html;
            });

        // Listen
        if (std::regex_match(line, std::regex("^\\s*-\\s(.+)"))) {
            line = "<li>" + std::string(in_list_item ? "\t" : "") + std::string(in_block_quote ? "\n" : "") + std::regex_replace(std::regex_replace(std::regex_replace(line, escape_regex, std::strdup("&amp;")), inline_code_regex,
                [&](const std::smatch& match) {
                    const auto& code = match[1].str();
                    std::string html = "<code>";
                    html += std::regex_replace(code, escape_regex, std::strdup("&amp;"));
                    html += "</code>";
                    return html;
                }),
                link_regex,
                [&](const std::smatch& match) {
                    const auto& text = match[1].str();
                    const auto& url = match[3].str();
                    std::string html = "<a href=\"";
                    html += url;
                    html += "\">";
                    html += text;
                    html += "</a>";
                    return html;
                }) + "</li>\n";
            in_list_item = !in_list_item;
        } else {
            line += "\n";
            in_list_item = false;
        }

        // Block-Zitate
        if (std::regex_match(line, std::regex("^> +(.+)"))) {
            line = std::string(in_block_quote ? "\n" : "") + std::string(in_list_item ? "\n" : "") + "<blockquote>" + std::regex_replace(std::regex_replace(line, escape_regex, std::strdup("&amp;")), inline_code_regex,
                [&](const std::smatch& match) {
                    const auto& code = match[1].str();
                    std::string html = "<code>";
                    html += std::regex_replace(code, escape_regex, std::strdup("&amp;"));
                    html += "</code>";
                    return html;
                }) + "</blockquote>\n";
            in_block_quote = !in_block_quote;
        } else {
            line += "\n";
            in_block_quote = false;
        }

        // HTML-Entitäten
        for (const auto& [char, entity] : html_entities) {
            line = std::regex_replace(line, std::regex(std::string(1, char)), entity.entity);
        }

        html_text += line;
    }

    return html_text;
}

// Hilfsfunktion zum Trennen einer Zeichenkette in eine Vektor von Zeilen
std::vector<std::string> split(const std::string& str, char delim) {
    std::stringstream ss(str);
    std::string item;
    std::vector<std::string> tokens;
    while (std::getline(ss, item, delim)) {
        tokens.push_back(std::move(item));
    }
    return tokens;
}
```

Dieser Code umfasst die folgenden Funktionalitäten:

- Konstruktor für die HTML-Entitäten
- Hash-Map für die HTML-Entitäten
- Funktion zum Formatieren des Markdown-Texts in HTML
- Reguläre Ausdrücke für die verschiedenen Markdown-Konstrukte
- HTML-Formatierung für die verschiedenen Markdown-Konstrukte
- Hilfsfunktion zum Trennen einer Zeichenkette in eine Vektor von Zeilen

Sie können die Funktion wie folgt aufrufen:

```cpp
#include <iostream>

int main() {
    std::string markdown_text = "H1-Titel\n"
                                 "## H2-Titel\n"
                                 "### H3-Titel\n"
                                 "\n"
                                 "Text mit **Fettdarstellung** und *normaler Darstellung*\n"
                                 "und auch [Link](https://example.com/).\n"
                                 "\n"
                                 "- Liste-Element 1\n"
                                 "  - Unter-Element\n"
                                 "  - Unter-Element 2\n"
                                 "- Liste-Element 2\n"
