#include <iostream>

using namespace std;

// Funktion zum finden der gemeinsamen Elemente in zwei Arrays
void gemeinsameElemente(int arr1[], int arr2[], int n1, int n2) {
    // Sortieren der Arrays aufsteigend
    sort(arr1, arr1 + n1);
    sort(arr2, arr2 + n2);

    int I = 0, j = 0;

    // Iterieren durch beide Arrays und vergleichen
    while (i < n1 && j < n2) {
        if (arr1[i] < arr2[j]) {
            i++;
        } else if (arr1[i] > arr2[j]) {
            j++;
        } else {
            // Elemente sind gleich, drucken aus und beide Indizes vorwärts setzen
            cout << arr1[i] << " ";

            i++;
            j++;
        }
    }
}

int main() {
    int arr1[] = { 2, 4, 5, 7, 9 };
    int arr2[] = { 3, 4, 6, 7, 8 };

    int n1 = sizeof(arr1) / sizeof(arr1[0]);
    int n2 = sizeof(arr2) / sizeof(arr2[0]);

    // Aufrufen der Funktion zum finden der gemeinsamen Elemente
    gemeinsameElemente(arr1, arr2, n1, n2);

    return 0;
}
```

Die Funktion `gemeinsameElemente` nimmt vier Argumente entgegen: die beiden Arrays als Arrays von ganzen Zahlen, sowie deren Größen als Anzahl von Elementen. Die Arrays werden vorab sortiert, sodass sie aufsteigend geordnet sind. Die Funktion iteriert dann durch beide Arrays und vergleicht die Elemente, bis alle Elemente eines der Arrays verarbeitet wurden. Wenn ein Element des ersten Arrays kleiner als das zweite ist, wird der Index des ersten Arrays um eins vorwärts gesetzt. Wenn das Element des zweiten Arrays kleiner ist, wird der Index des zweiten Arrays um eins vorwärts gesetzt. Wenn die beiden Elemente gleich sind, drucken wir das gemeinsame Element aus und setzen beide Indizes um eins vorwärts.

Die Implementierung kann für Arrays beliebiger Größe und Datentypen verwendet werden, solange die verglichenen Elemente jeweils vergleichbar sind.

